export function SearchToken({
  field = "{{field}}",
  value = "{{value}}",
  kind = "{{kind}}",
  accent = "{{accent}}",
}) {
  const styles = {
    status: { background: "#A8E6C140", color: "#1c5c37" },
    assignee: { background: "#BFD9F250", color: "#1c3d5c" },
    label: { background: "#F5C2E050", color: "#5c1c47" },
  };
  const kindStyle = styles[kind] ?? styles.status;
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 5, fontFamily: "system-ui, sans-serif", fontSize: 13,
      padding: "5px 6px 5px 9px", borderRadius: 999, ...kindStyle,
    }}>
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true" style={{ flex: "none" }}>
        <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" />
      </svg>
      <span style={{ whiteSpace: "nowrap" }}>{field}:<b>{value}</b></span>
      <button type="button" aria-label={`Remove filter: ${field} — ${value}`} style={{
        flex: "none", display: "grid", placeItems: "center", width: 16, height: 16, border: "none",
        borderRadius: "50%", background: "#24143014", color: "inherit", cursor: "pointer",
      }}>
        <svg width="10" height="10" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" strokeWidth="3" strokeLinecap="round" /></svg>
      </button>
    </span>
  );
}
